import java.util.List;
import java.util.function.Function;

/** Runs every few seconds on a scheduler thread and copies carrier tracking status into our records. */
public class CarrierSync {
    private final ShipmentRepository repository;
    private final Function<String, String> carrierStatus;
    private final List<String> trackedIds;

    public CarrierSync(ShipmentRepository repository, Function<String, String> carrierStatus, List<String> trackedIds) {
        this.repository = repository;
        this.carrierStatus = carrierStatus;
        this.trackedIds = List.copyOf(trackedIds);
    }

    public void tick() {
        for (String id : trackedIds) {
            String status = carrierStatus.apply(id);
            Shipment current = repository.load(id);
            repository.save(current.withStatus(status));
        }
    }
}
import java.util.concurrent.ConcurrentHashMap;

public class InMemoryStore implements KeyValueStore {
    private final ConcurrentHashMap<String, String> data = new ConcurrentHashMap<>();

    @Override
    public String get(String key) {
        return data.get(key);
    }

    @Override
    public void put(String key, String value) {
        data.put(key, value);
    }
}
public interface KeyValueStore {
    String get(String key);

    void put(String key, String value);
}
/** Called from the operator UI when someone tags a shipment (e.g. "fragile", "VIP"). */
public class LabelService {
    private final ShipmentRepository repository;

    public LabelService(ShipmentRepository repository) {
        this.repository = repository;
    }

    public void setLabel(String id, String label) {
        if (label != null && (label.contains("\t") || label.contains("\n"))) {
            throw new IllegalArgumentException("label must be a single line");
        }
        Shipment current = repository.load(id);
        repository.save(current.withLabel(label));
    }
}
public record Shipment(String id, String status, String label) {
    public Shipment withStatus(String newStatus) {
        return new Shipment(id, newStatus, label);
    }

    public Shipment withLabel(String newLabel) {
        return new Shipment(id, status, newLabel);
    }
}
public class ShipmentRepository {
    private static final String PREFIX = "shipment:";

    private final KeyValueStore store;

    public ShipmentRepository(KeyValueStore store) {
        this.store = store;
    }

    public Shipment load(String id) {
        String raw = store.get(PREFIX + id);
        if (raw == null) {
            return new Shipment(id, "UNKNOWN", null);
        }
        String[] parts = raw.split("\t", -1);
        String label = parts[1].isEmpty() ? null : parts[1];
        return new Shipment(id, parts[0], label);
    }

    public void save(Shipment shipment) {
        String label = shipment.label() == null ? "" : shipment.label();
        store.put(PREFIX + shipment.id(), shipment.status() + "\t" + label);
    }
}

